package com.fixora.api;
import com.fixora.model.*; import com.fixora.repo.*; import com.fixora.security.TokenService; import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.core.Authentication; import org.springframework.transaction.annotation.Transactional; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.time.*; import java.util.*; import java.security.SecureRandom; import java.nio.charset.StandardCharsets; import java.security.MessageDigest;
@RestController @RequestMapping("/api/v1") public class ApiController {
 private final UserRepo users; private final ServiceRepo services; private final BookingRepo bookings; private final ChatRepo chats; private final ReviewRepo reviews; private final PasswordEncoder encoder; private final TokenService tokens; private final SecureRandom random=new SecureRandom(); private final java.util.concurrent.ConcurrentHashMap<String,String> devOtps=new java.util.concurrent.ConcurrentHashMap<>();
 public ApiController(UserRepo u,ServiceRepo s,BookingRepo b,ChatRepo c,ReviewRepo r,PasswordEncoder e,TokenService t){users=u;services=s;bookings=b;chats=c;reviews=r;encoder=e;tokens=t;}
 record Register(@NotBlank String name,@Email @NotBlank String email,@Size(min=8,max=100) String password,@Pattern(regexp="CUSTOMER|SERVICER") String role){}
 record Login(@Email @NotBlank String email,@NotBlank String password){}
 record BookingInput(@NotBlank String serviceCode,String description,@NotBlank String address,@NotBlank String city,@NotNull LocalDateTime scheduledAt,boolean customRequest,Integer agreedPricePaise,String quoteNote){}
 record MessageInput(@NotBlank @Size(max=2000) String body){} record ReviewInput(@Min(1) @Max(5) int stars,String comment){} record OtpInput(@NotBlank String code){}
 @GetMapping("/health") Map<String,Object> health(){return Map.of("application","fixora","status","UP","apiVersion",1);}
 @GetMapping("/services") List<Map<String,Object>> serviceList(){return services.findByActiveTrue().stream().map(s->Map.<String,Object>of("id",s.id,"code",s.code,"name",s.name,"description",s.description,"pricePaise",s.pricePaise)).toList();}
 
@PostMapping("/auth/register")
ResponseEntity<?> register(@Valid @RequestBody Register in) {
    return ResponseEntity.status(410)
        .body(Map.of("error",
            "Direct registration is disabled. Use email OTP verification."));
}

 @PostMapping("/auth/login") ResponseEntity<?> login(@Valid @RequestBody Login in){User u=users.findByEmailIgnoreCase(in.email().trim()).orElse(null);if(u==null||!u.enabled||!encoder.matches(in.password(),u.passwordHash))return ResponseEntity.status(401).body(Map.of("error","Invalid email or password"));return ResponseEntity.ok(authPayload(u));}
 private Map<String,Object> authPayload(User u){return Map.of("token",tokens.issue(u.id,u.role,u.email),"user",Map.of("id",u.id,"name",u.name,"email",u.email,"role",u.role));}
 private User current(Authentication a){String[] p=a.getName().split("\\|",3);return users.findById(Long.valueOf(p[0])).orElseThrow();}
 private boolean admin(User u){return u.role.equals("ADMIN");}
 @GetMapping("/me") Map<String,Object> me(Authentication a){User u=current(a);return Map.of("id",u.id,"name",u.name,"email",u.email,"role",u.role);}
 @PostMapping("/bookings") @Transactional ResponseEntity<?> create(@Valid @RequestBody BookingInput in,Authentication a){User u=current(a);if(!u.role.equals("CUSTOMER"))return ResponseEntity.status(403).body(Map.of("error","Only customers can create bookings"));ServiceItem item=services.findByCodeAndActiveTrue(in.serviceCode()).orElse(null);if(item==null)return ResponseEntity.badRequest().body(Map.of("error","Choose a valid service"));if(in.description()==null||in.description().isBlank()||in.address().isBlank()||in.city().isBlank())return ResponseEntity.badRequest().body(Map.of("error","Description, address and city are required"));int price=item.pricePaise;if(in.customRequest()){if(in.agreedPricePaise()==null||in.agreedPricePaise()<1)return ResponseEntity.badRequest().body(Map.of("error","Custom requests require a confirmed fixed price before booking"));price=in.agreedPricePaise();}else if(in.agreedPricePaise()!=null&&in.agreedPricePaise()!=item.pricePaise)return ResponseEntity.badRequest().body(Map.of("error","Package price must match the catalog price"));Booking b=new Booking();b.publicId="FX-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();b.customer=u;b.serviceItem=item;b.description=in.description().trim();b.address=in.address().trim();b.city=in.city().trim();b.scheduledAt=in.scheduledAt();b.agreedPricePaise=price;b.customRequest=in.customRequest();b.quoteNote=in.quoteNote();b.status="PENDING_ASSIGNMENT";bookings.save(b);return ResponseEntity.status(201).body(bookingDto(b,u));}
 @GetMapping("/bookings") List<Map<String,Object>> list(Authentication a){User u=current(a);List<Booking> all=admin(u)?bookings.findAllByOrderByCreatedAtDesc():u.role.equals("SERVICER")?bookings.findByServicerIdOrderByCreatedAtDesc(u.id):bookings.findByCustomerIdOrderByCreatedAtDesc(u.id);if(u.role.equals("SERVICER")){List<Booking> available=bookings.findAllByOrderByCreatedAtDesc().stream().filter(b->b.status.equals("PENDING_ASSIGNMENT")&&b.servicer==null).toList();Map<Long,Booking> merged=new LinkedHashMap<>();available.forEach(b->merged.put(b.id,b));all.forEach(b->merged.put(b.id,b));all=new ArrayList<>(merged.values());}return all.stream().map(b->bookingDto(b,u)).toList();}
 @PostMapping("/bookings/{id}/accept") @Transactional ResponseEntity<?> accept(@PathVariable String id,Authentication a){User u=current(a);if(!u.role.equals("SERVICER"))return ResponseEntity.status(403).body(Map.of("error","Only servicers can accept jobs"));Booking b=bookings.findByPublicId(id).orElse(null);if(b==null)return ResponseEntity.notFound().build();if(!b.status.equals("PENDING_ASSIGNMENT")||b.servicer!=null)return ResponseEntity.status(409).body(Map.of("error","This job has already been accepted"));b.servicer=u;b.status="ACCEPTED";return ResponseEntity.ok(bookingDto(bookings.save(b),u));}
 @PatchMapping("/bookings/{id}/status") @Transactional ResponseEntity<?> status(@PathVariable String id,@RequestBody Map<String,String> body,Authentication a){User u=current(a);Booking b=bookings.findByPublicId(id).orElse(null);if(b==null)return ResponseEntity.notFound().build();if(!admin(u)&&!Objects.equals(b.servicer==null?null:b.servicer.id,u.id))return ResponseEntity.status(403).body(Map.of("error","Only assigned servicer or admin can update status"));String next=body.getOrDefault("status","");Set<String> allowed=Set.of("ON_THE_WAY","IN_PROGRESS","COMPLETED");if(!allowed.contains(next))return ResponseEntity.badRequest().body(Map.of("error","Unsupported status transition"));if(next.equals("ON_THE_WAY")&&!b.status.equals("ACCEPTED"))return ResponseEntity.badRequest().body(Map.of("error","Booking must be accepted first"));if(next.equals("IN_PROGRESS")&&!b.status.equals("ARRIVED"))return ResponseEntity.badRequest().body(Map.of("error","Verify arrival OTP before starting work"));if(next.equals("COMPLETED")&&!b.status.equals("IN_PROGRESS"))return ResponseEntity.badRequest().body(Map.of("error","Work must be in progress before completion"));if(next.equals("ON_THE_WAY")){String code=String.format("%06d",random.nextInt(1000000));b.otpHash=hash(code);b.otpExpiresAt=Instant.now().plusSeconds(900);if(Boolean.parseBoolean(System.getenv().getOrDefault("OTP_TEST_REVEAL","false")))devOtps.put(b.publicId,code);}b.status=next;Booking saved=bookings.save(b);Map<String,Object> out=new LinkedHashMap<>(bookingDto(saved,u));return ResponseEntity.ok(out);}
 @GetMapping("/bookings/{id}/arrival-code") ResponseEntity<?> customerOtp(@PathVariable String id,Authentication a){User u=current(a);Booking b=bookings.findByPublicId(id).orElse(null);if(b==null)return ResponseEntity.notFound().build();if(!Objects.equals(b.customer.id,u.id)&&!admin(u))return ResponseEntity.status(403).body(Map.of("error","Customer-only endpoint"));if(Boolean.parseBoolean(System.getenv().getOrDefault("OTP_TEST_REVEAL","false"))){String code=devOtps.get(id);if(code!=null)return ResponseEntity.ok(Map.of("code",code,"expiresAt",b.otpExpiresAt,"warning","Development-only OTP reveal; disable before production."));}return ResponseEntity.status(503).body(Map.of("error","OTP delivery is not configured. Enable OTP_TEST_REVEAL only for local development; configure a secure delivery provider before production."));}
 @PostMapping("/bookings/{id}/verify-arrival") @Transactional ResponseEntity<?> verifyOtp(@PathVariable String id,@Valid @RequestBody OtpInput in,Authentication a){User u=current(a);Booking b=bookings.findByPublicId(id).orElse(null);if(b==null)return ResponseEntity.notFound().build();if(b.servicer==null||!Objects.equals(b.servicer.id,u.id))return ResponseEntity.status(403).body(Map.of("error","Only assigned servicer can verify arrival"));if(!b.status.equals("ON_THE_WAY")||b.otpHash==null||b.otpExpiresAt==null||b.otpExpiresAt.isBefore(Instant.now())||!b.otpHash.equals(hash(in.code())))return ResponseEntity.status(400).body(Map.of("error","Invalid or expired arrival code"));b.otpHash=null;b.otpExpiresAt=null;devOtps.remove(id);b.status="ARRIVED";return ResponseEntity.ok(bookingDto(bookings.save(b),u));}
 @PostMapping("/bookings/{id}/cancel") @Transactional ResponseEntity<?> cancel(@PathVariable String id,Authentication a){User u=current(a);Booking b=bookings.findByPublicId(id).orElse(null);if(b==null)return ResponseEntity.notFound().build();if(!admin(u)&&!Objects.equals(b.customer.id,u.id))return ResponseEntity.status(403).body(Map.of("error","Only booking customer or admin can cancel"));if(Set.of("COMPLETED","CANCELLED","IN_PROGRESS").contains(b.status))return ResponseEntity.badRequest().body(Map.of("error","This booking can no longer be cancelled here"));b.status="CANCELLED";return ResponseEntity.ok(bookingDto(bookings.save(b),u));}
 @GetMapping("/bookings/{id}/messages") ResponseEntity<?> messages(@PathVariable String id,Authentication a){User u=current(a);Booking b=bookings.findByPublicId(id).orElse(null);if(b==null)return ResponseEntity.notFound().build();if(!participant(b,u)&&!admin(u))return ResponseEntity.status(403).body(Map.of("error","Not a booking participant"));return ResponseEntity.ok(chats.findByBookingPublicIdOrderBySentAtAsc(id).stream().map(m->Map.of("id",m.id,"sender",m.sender.name,"senderRole",m.sender.role,"body",m.body,"sentAt",m.sentAt)).toList());}
 @PostMapping("/bookings/{id}/messages") ResponseEntity<?> sendMessage(@PathVariable String id,@Valid @RequestBody MessageInput in,Authentication a){User u=current(a);Booking b=bookings.findByPublicId(id).orElse(null);if(b==null)return ResponseEntity.notFound().build();if(!participant(b,u))return ResponseEntity.status(403).body(Map.of("error","Only booking participants can chat"));if(b.status.equals("CANCELLED"))return ResponseEntity.badRequest().body(Map.of("error","Cancelled booking chat is closed"));ChatMessage m=new ChatMessage();m.booking=b;m.sender=u;m.body=in.body().trim();chats.save(m);return ResponseEntity.status(201).body(Map.of("id",m.id,"sender",u.name,"senderRole",u.role,"body",m.body,"sentAt",m.sentAt));}
 @PostMapping("/bookings/{id}/reviews") ResponseEntity<?> review(@PathVariable String id,@Valid @RequestBody ReviewInput in,Authentication a){User u=current(a);Booking b=bookings.findByPublicId(id).orElse(null);if(b==null)return ResponseEntity.notFound().build();if(!Objects.equals(b.customer.id,u.id)||!b.status.equals("COMPLETED"))return ResponseEntity.status(403).body(Map.of("error","Only the customer can review a completed booking"));if(reviews.existsByBookingIdAndCustomerId(b.id,u.id))return ResponseEntity.status(409).body(Map.of("error","Review already submitted"));Review r=new Review();r.booking=b;r.customer=u;r.stars=in.stars();r.comment=in.comment()==null?"":in.comment().trim();reviews.save(r);return ResponseEntity.status(201).body(Map.of("id",r.id,"stars",r.stars,"comment",r.comment));}
 @GetMapping("/admin/summary") ResponseEntity<?> adminSummary(Authentication a){User u=current(a);if(!admin(u))return ResponseEntity.status(403).body(Map.of("error","Admin only"));return ResponseEntity.ok(Map.of("users",users.count(),"bookings",bookings.count(),"services",services.count(),"reviews",reviews.count()));}
 private boolean participant(Booking b,User u){return Objects.equals(b.customer.id,u.id)||(b.servicer!=null&&Objects.equals(b.servicer.id,u.id));}
 private String hash(String s){try{return Base64.getEncoder().encodeToString(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private Map<String,Object> bookingDto(Booking b,User viewer){Map<String,Object> m=new LinkedHashMap<>();m.put("id",b.publicId);m.put("service",b.serviceItem.name);m.put("serviceCode",b.serviceItem.code);m.put("description",b.description);m.put("address",b.address);m.put("city",b.city);m.put("scheduledAt",b.scheduledAt);m.put("pricePaise",b.agreedPricePaise);m.put("priceRupees",b.agreedPricePaise/100.0);m.put("status",b.status);m.put("customRequest",b.customRequest);m.put("customer",Map.of("name",b.customer.name));m.put("servicer",b.servicer==null?null:Map.of("name",b.servicer.name,"id","FXS-"+b.servicer.id));m.put("createdAt",b.createdAt);return m;}
}

